import{_ as p,a0 as l,w as d,s as r,I as e,x as a,a1 as n,A as t,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？ | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？ | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20190527 How To Enable Or Disable SSH Access For A Particular User Or Group In Linux","title":"如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？","tag":"202003","desc":""},"relativePath":"202003/20190527 How To Enable Or Disable SSH Access For A Particular User Or Group In Linux.md","filePath":"[post].md"}'),o={name:"202003/20190527 How To Enable Or Disable SSH Access For A Particular User Or Group In Linux.md"};function c(u,s,g,k,b,f){const i=l("Link");return d(),r("div",null,[s[18]||(s[18]=e("h1",{id:"如何在-linux-上为特定的用户或用户组启用或禁用-ssh",tabindex:"-1"},[a("如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？ "),e("a",{class:"header-anchor",href:"#如何在-linux-上为特定的用户或用户组启用或禁用-ssh","aria-label":"Permalink to “如何在 Linux 上为特定的用户或用户组启用或禁用 SSH？”"},"​")],-1)),s[19]||(s[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202003/23/105915r1azn34i82sp48ca.jpg",alt:""})],-1)),s[20]||(s[20]=e("p",null,"由于你的公司标准规定，你可能只能允许部分人访问 Linux 系统。或者你可能只能够允许几个用户组中的用户访问 Linux 系统。那么如何实现这样的要求呢？最好的方法是什么呢？如何使用一个简单的方法去实现呢？",-1)),s[21]||(s[21]=e("p",null,[a("是的，我们会有很多种方法去实现它。但是我们应该使用简单轻松的方法。为了简单轻松的完成目的，我们可以通过对 "),e("code",null,"/etc/ssh/sshd_config"),a(" 文件做必要的修改来实现。在这篇文章中我们将会向你展示实现要求的详细步骤。")],-1)),e("p",null,[s[1]||(s[1]=a("为什么我们要这样做呢？是出于安全的原因。你可以访问",-1)),n(i,{href:"https://www.2daygeek.com/category/ssh-tutorials/"},{default:t(()=>[...s[0]||(s[0]=[a("这个链接",-1)])]),_:1}),s[2]||(s[2]=a("来获取更多关于 openSSH 的使用方法。",-1))]),s[22]||(s[22]=h(`<h3 id="什么是-ssh" tabindex="-1">什么是 SSH ？ <a class="header-anchor" href="#什么是-ssh" aria-label="Permalink to “什么是 SSH ？”">​</a></h3><p>openssh 全称为 OpenBSD Secure Shell。Secure Shell（ssh）是一个自由开源的网络工具，它能让我们在一个不安全的网络中通过使用 Secure Shell（SSH）协议来安全访问远程主机。</p><p>它采用了客户端-服务器架构（C/S），拥有用户身份认证、加密、在计算机和隧道之间传输文件等功能。</p><p>我们也可以用 <code>telnet</code> 或 <code>rcp</code> 等传统工具来完成，但是这些工具都不安全，因为它们在执行任何动作时都会使用明文来传输密码。</p><h3 id="如何在-linux-中允许用户使用-ssh" tabindex="-1">如何在 Linux 中允许用户使用 SSH？ <a class="header-anchor" href="#如何在-linux-中允许用户使用-ssh" aria-label="Permalink to “如何在 Linux 中允许用户使用 SSH？”">​</a></h3><p>通过以下内容，我们可以为指定的用户或用户列表启用 <code>ssh</code> 访问。如果你想要允许多个用户，那么你可以在添加用户时在同一行中用空格来隔开他们。</p><p>为了达到目的只需要将下面的值追加到 <code>/etc/ssh/sshd_config</code> 文件中去。 在这个例子中， 我们将会允许用户 <code>user3</code> 使用 ssh。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;AllowUsers user3&quot; &gt;&gt; /etc/ssh/sshd_config</span></span></code></pre></div><p>你可以运行下列命令再次检查是否添加成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/ssh/sshd_config | grep -i allowusers</span></span>
<span class="line"><span>AllowUsers user3</span></span></code></pre></div><p>这样就行了， 现在只需要重启 <code>ssh</code> 服务和见证奇迹了。（下面这两条命令效果相同， 请根据你的服务管理方式选择一条执行即可）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart sshd</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># service restart sshd</span></span></code></pre></div><p>接下来很简单，只需打开一个新的终端或者会话尝试用不同的用户身份访问 Linux 系统。是的，这里 <code>user2</code> 用户是不被允许使用 SSH 登录的并且会得到如下所示的错误信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user2@192.168.1.4</span></span>
<span class="line"><span>user2@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:00:35 CentOS7 sshd[4900]: User user2 from 192.168.1.6 not allowed because not listed in AllowUsers</span></span>
<span class="line"><span>Mar 29 02:00:35 CentOS7 sshd[4900]: input_userauth_request: invalid user user2 [preauth]</span></span>
<span class="line"><span>Mar 29 02:00:40 CentOS7 unix_chkpwd[4902]: password check failed for user (user2)</span></span>
<span class="line"><span>Mar 29 02:00:40 CentOS7 sshd[4900]: pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=192.168.1.6  user=user2</span></span>
<span class="line"><span>Mar 29 02:00:43 CentOS7 sshd[4900]: Failed password for invalid user user2 from 192.168.1.6 port 42568 ssh2</span></span></code></pre></div><p>与此同时用户 <code>user3</code> 被允许登入系统因为他在被允许的用户列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user3@192.168.1.4</span></span>
<span class="line"><span>user3@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>[user3@CentOS7 ~]$</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:01:13 CentOS7 sshd[4939]: Accepted password for user3 from 192.168.1.6 port 42590 ssh2</span></span>
<span class="line"><span>Mar 29 02:01:13 CentOS7 sshd[4939]: pam_unix(sshd:session): session opened for user user3 by (uid=0)</span></span></code></pre></div><h3 id="如何在-linux-中阻止用户使用-ssh" tabindex="-1">如何在 Linux 中阻止用户使用 SSH ？ <a class="header-anchor" href="#如何在-linux-中阻止用户使用-ssh" aria-label="Permalink to “如何在 Linux 中阻止用户使用 SSH ？”">​</a></h3><p>通过以下内容，我们可以配置指定的用户或用户列表禁用 <code>ssh</code>。如果你想要禁用多个用户，那么你可以在添加用户时在同一行中用空格来隔开他们。</p><p>为了达到目的只需要将以下值追加到 <code>/etc/ssh/sshd_config</code> 文件中去。 在这个例子中， 我们将禁用用户 <code>user1</code> 使用 <code>ssh</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;DenyUsers user1&quot; &gt;&gt; /etc/ssh/sshd_config</span></span></code></pre></div><p>你可以运行下列命令再次检查是否添加成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/ssh/sshd_config | grep -i denyusers</span></span>
<span class="line"><span>DenyUsers user1</span></span></code></pre></div><p>这样就行了， 现在只需要重启 <code>ssh</code> 服务和见证奇迹了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart sshd</span></span>
<span class="line"><span>活</span></span>
<span class="line"><span># service restart sshd</span></span></code></pre></div><p>接下来很简单，只需打开一个新的终端或者会话，尝试使用被禁用的用户身份被访问 Linux 系统。是的，这里 <code>user1</code> 用户在禁用名单中。所以，当你尝试登录时，你将会得到如下所示的错误信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user1@192.168.1.4</span></span>
<span class="line"><span>user1@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 01:53:42 CentOS7 sshd[4753]: User user1 from 192.168.1.6 not allowed because listed in DenyUsers</span></span>
<span class="line"><span>Mar 29 01:53:42 CentOS7 sshd[4753]: input_userauth_request: invalid user user1 [preauth]</span></span>
<span class="line"><span>Mar 29 01:53:46 CentOS7 unix_chkpwd[4755]: password check failed for user (user1)</span></span>
<span class="line"><span>Mar 29 01:53:46 CentOS7 sshd[4753]: pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=192.168.1.6  user=user1</span></span>
<span class="line"><span>Mar 29 01:53:48 CentOS7 sshd[4753]: Failed password for invalid user user1 from 192.168.1.6 port 42522 ssh2</span></span></code></pre></div><h3 id="如何在-linux-中允许用户组使用-ssh" tabindex="-1">如何在 Linux 中允许用户组使用 SSH? <a class="header-anchor" href="#如何在-linux-中允许用户组使用-ssh" aria-label="Permalink to “如何在 Linux 中允许用户组使用 SSH?”">​</a></h3><p>通过以下内容，我们可以允许一个指定的组或多个组使用 <code>ssh</code>。</p><p>如果你想要允许多个组使用 <code>ssh</code> 那么你在添加用户组时需要在同一行中使用空格来隔开他们。</p><p>为了达到目的只需将以下值追加到 <code>/etc/ssh/sshd_config</code> 文件中去。在这个例子中，我们将允许 <code>2g-admin</code> 组使用 ssh。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;AllowGroups 2g-admin&quot; &gt;&gt; /etc/ssh/sshd_config</span></span></code></pre></div><p>你可以运行下列命令再次检查是否添加成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/ssh/sshd_config | grep -i allowgroups</span></span>
<span class="line"><span>AllowGroups 2g-admin</span></span></code></pre></div><p>运行下列命令查看属于该用户组的用户有哪些。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getent group 2g-admin</span></span>
<span class="line"><span>2g-admin:x:1005:user1,user2,user3</span></span></code></pre></div><p>这样就行了， 现在只需要重启 <code>ssh</code> 服务和见证奇迹了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart sshd</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># service restart sshd</span></span></code></pre></div><p>是的， <code>user1</code> 被允许登入系统因为用户 <code>user1</code> 属于 <code>2g-admin</code> 组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user1@192.168.1.4</span></span>
<span class="line"><span>user1@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>[user1@CentOS7 ~]$</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:10:21 CentOS7 sshd[5165]: Accepted password for user1 from 192.168.1.6 port 42640 ssh2</span></span>
<span class="line"><span>Mar 29 02:10:22 CentOS7 sshd[5165]: pam_unix(sshd:session): session opened for user user1 by (uid=0)</span></span></code></pre></div><p>是的， <code>user2</code> 被允许登入系统因为用户 <code>user2</code> 同样属于 <code>2g-admin</code> 组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user2@192.168.1.4</span></span>
<span class="line"><span>user2@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>[user2@CentOS7 ~]$</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:10:38 CentOS7 sshd[5225]: Accepted password for user2 from 192.168.1.6 port 42642 ssh2</span></span>
<span class="line"><span>Mar 29 02:10:38 CentOS7 sshd[5225]: pam_unix(sshd:session): session opened for user user2 by (uid=0)</span></span></code></pre></div><p>当你尝试使用其他不在被允许的组中的用户去登入系统时， 你将会得到如下所示的错误信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh ladmin@192.168.1.4</span></span>
<span class="line"><span>ladmin@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:12:36 CentOS7 sshd[5306]: User ladmin from 192.168.1.6 not allowed because none of user&#39;s groups are listed in AllowGroups</span></span>
<span class="line"><span>Mar 29 02:12:36 CentOS7 sshd[5306]: input_userauth_request: invalid user ladmin [preauth]</span></span>
<span class="line"><span>Mar 29 02:12:56 CentOS7 unix_chkpwd[5310]: password check failed for user (ladmin)</span></span>
<span class="line"><span>Mar 29 02:12:56 CentOS7 sshd[5306]: pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=192.168.1.6  user=ladmin</span></span>
<span class="line"><span>Mar 29 02:12:58 CentOS7 sshd[5306]: Failed password for invalid user ladmin from 192.168.1.6 port 42674 ssh2</span></span></code></pre></div><h3 id="如何在-linux-中阻止用户组使用-ssh" tabindex="-1">如何在 Linux 中阻止用户组使用 SSH？ <a class="header-anchor" href="#如何在-linux-中阻止用户组使用-ssh" aria-label="Permalink to “如何在 Linux 中阻止用户组使用 SSH？”">​</a></h3><p>通过以下内容，我们可以禁用指定的组或多个组使用 <code>ssh</code>。</p><p>如果你想要禁用多个用户组使用 <code>ssh</code>，那么你需要在添加用户组时在同一行中使用空格来隔开他们。</p><p>为了达到目的只需要将下面的值追加到 <code>/etc/ssh/sshd_config</code> 文件中去。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &quot;DenyGroups 2g-admin&quot; &gt;&gt; /etc/ssh/sshd_config</span></span></code></pre></div><p>你可以运行下列命令再次检查是否添加成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># # cat /etc/ssh/sshd_config | grep -i denygroups</span></span>
<span class="line"><span>DenyGroups 2g-admin</span></span>
<span class="line"><span></span></span>
<span class="line"><span># getent group 2g-admin</span></span>
<span class="line"><span>2g-admin:x:1005:user1,user2,user3</span></span></code></pre></div><p>这样就行了， 现在只需要重启 <code>ssh</code> 服务和见证奇迹了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart sshd</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># service restart sshd</span></span></code></pre></div><p>是的 <code>user1</code> 不被允许登入系统，因为他是 <code>2g-admin</code> 用户组中的一员。他属于被禁用 <code>ssh</code> 的组中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh user1@192.168.1.4</span></span>
<span class="line"><span>user1@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:17:32 CentOS7 sshd[5400]: User user1 from 192.168.1.6 not allowed because a group is listed in DenyGroups</span></span>
<span class="line"><span>Mar 29 02:17:32 CentOS7 sshd[5400]: input_userauth_request: invalid user user1 [preauth]</span></span>
<span class="line"><span>Mar 29 02:17:38 CentOS7 unix_chkpwd[5402]: password check failed for user (user1)</span></span>
<span class="line"><span>Mar 29 02:17:38 CentOS7 sshd[5400]: pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=192.168.1.6  user=user1</span></span>
<span class="line"><span>Mar 29 02:17:41 CentOS7 sshd[5400]: Failed password for invalid user user1 from 192.168.1.6 port 42710 ssh2</span></span></code></pre></div><p>除了 <code>2g-admin</code> 用户组之外的用户都可以使用 ssh 登入系统。 例如，<code>ladmin</code> 等用户就允许登入系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh ladmin@192.168.1.4</span></span>
<span class="line"><span>ladmin@192.168.1.4&#39;s password: </span></span>
<span class="line"><span>[ladmin@CentOS7 ~]$</span></span></code></pre></div><p>输出:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mar 29 02:19:13 CentOS7 sshd[5432]: Accepted password for ladmin from 192.168.1.6 port 42716 ssh2</span></span>
<span class="line"><span>Mar 29 02:19:13 CentOS7 sshd[5432]: pam_unix(sshd:session): session opened for user ladmin by (uid=0)</span></span></code></pre></div><hr>`,73)),e("p",null,[s[4]||(s[4]=a("via: ",-1)),n(i,{href:"https://www.2daygeek.com/allow-deny-enable-disable-ssh-access-user-group-in-linux/"},{default:t(()=>[...s[3]||(s[3]=[a("https://www.2daygeek.com/allow-deny-enable-disable-ssh-access-user-group-in-linux/",-1)])]),_:1})]),e("p",null,[s[9]||(s[9]=a("作者：",-1)),n(i,{href:"http://www.2daygeek.com/author/2daygeek/"},{default:t(()=>[...s[5]||(s[5]=[a("2daygeek",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),n(i,{href:"https://github.com/way-ww"},{default:t(()=>[...s[7]||(s[7]=[a("way-ww",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const x=p(o,[["render",c]]);export{C as __pageData,x as default};
